-- CPF persistent data-quality runtime/reconcile queries
SELECT RULE_ID,RULE_VERSION,FIELD_NAME,EXPRESSION,SEVERITY,RULE_STATE,UPDATED_AT FROM CPF_DATA_QUALITY_RULE ORDER BY RULE_ID,RULE_VERSION DESC;
SELECT QUARANTINE_ID,RECORD_ID,QUARANTINE_STATE,ROW_VERSION,UPDATED_BY,UPDATED_AT FROM CPF_DATA_QUALITY_QUARANTINE WHERE QUARANTINE_STATE IN ('QUARANTINED','CORRECTED') ORDER BY UPDATED_AT,QUARANTINE_ID;
SELECT OPERATION_ID,OPERATION_TYPE,QUARANTINE_ID,COMMAND_FINGERPRINT,ACTOR_ID,CREATED_AT FROM CPF_DATA_QUALITY_OPERATION ORDER BY CREATED_AT DESC;
